date) Return_Date, CASE WHEN Invoice_Date = \'\' OR Invoice_Date is null THEN cast(null as date) ELSE date(cast(Invoice_Date as datetime)) END as Invoice_Date, CASE WHEN Return_Initiated_Date = \'\' OR Return_Initiated_Date = \'0000-00-00\' THEN \'1970-01-01\' ELSE date(cast(Return_Initiated_Date as datetime)) END Return_Initiated_Date, Return_Type, replace(order_number,\'`\',\'\') as reference_code, split_part(replace(Order_Item_ID,\'`\',\'\'),\'_\',1) as saleorderitemcode, cast(null as string) serial_number, cast(null as string) Credit_Note_Id, Invoice_Number, cast(Return_Quantity as int) as Returned_quantity, cast(null as string) return_initiated_reason, cast(null as string) Seller_Return_Reason, (Channel_return_reason) Channel_return_reason, cast(null as string) Inventory_Status, companyProductId, cast(null as string) Creditnote_Number, cast(null as string) MP_Credit_Note_No, MP_Delivered_Date, Product_name, cast(null as date) RTO_Delivered_Date, Forward_Carrier_Name, Reverse_Carrier_Name, null Total_Credit_Note_Amount from maplemonk.easyecom_emmasleep_pending_returns_report epr where replace(Order_Item_ID,\'`\',\'\') not in (select distinct replace(Order_Item_ID,\'`\',\'\') from emmasleep_db.maplemonk.easyecom_emmasleep_returns_report) ) select * from returns qualify row_number() over (partition by reference_code,saleorderitemcode order by total_credit_note_amount desc) = 1 ; create or replace table emmasleep_db.maplemonk.emmasleep_db_returns_consolidated as SELECT replace(e.reference_code,\'#\',\'\') reference_code, e.SALEORDERITEMCODE, e.ORDER_ID, UPPER(e.order_status) AS order_status, CAST(e.ORDER_DATE AS TIMESTAMP_NTZ) AS Order_Date, CAST(DELIVERED_DATE AS TIMESTAMP_NTZ) AS Delivered_Date, UPPER(e.marketplace) AS marketplace, UPPER(e.marketplace) AS MARKETING_CHANNEL, UPPER(e.marketplace) AS SOURCE, UPPER(e.PRODUCT_NAME) AS PRODUCT_NAME, e.SKU, UPPER(e.product_category) AS product_category, UPPER(e.product_sub_category) AS product_sub_category, e.quantity AS order_quantity, UPPER(e.CITY) AS City, UPPER(e.STATE) AS State, e.pincode, UPPER(e.COURIER) AS Shipping_Courier, e.awb, e.name AS NAME, e.email AS EMAIL, CAST(NULL AS VARCHAR) AS return_request_number, CAST(NULL AS TIMESTAMP_NTZ) AS original_return_request_date, CAST(NULL AS NUMBER(38,0)) AS no_of_return_requests_initiated, CAST(NULL AS ARRAY) AS list_of_pickup_couriers_assigned, CAST(NULL AS TIMESTAMP_NTZ) AS return_approved_date, CAST(NULL AS TIMESTAMP_NTZ) AS return_refunded_at, CAST(NULL AS TIMESTAMP_NTZ) AS return_inspected_date, CAST(r.return_date AS TIMESTAMP_NTZ) AS return_date, CASE WHEN COALESCE(IFF(return_date IS NOT NULL, 1, NULL), e.return_flag) = 1 THEN \'Approved\' ELSE NULL END AS return_approval_status, CASE WHEN COALESCE(IFF(return_date IS NOT NULL, 1, NULL), e.return_flag) = 1 THEN \'return\' ELSE NULL END AS return_request_type, CASE WHEN LOWER(r.channel_return_reason) LIKE \'%lost%\' THEN \'lost\' WHEN LOWER(r.channel_return_reason) LIKE \'%exchange%\' THEN \'exchange\' WHEN (LOWER(r.channel_return_reason) LIKE \'%rto%\' OR LOWER(r.channel_return_reason) LIKE \'%not serviceable%\') THEN \'RTO\' WHEN r.channel_return_reason IS NOT NULL THEN \'return\' ELSE NULL END AS return_type, COALESCE(IFF(return_date IS NOT NULL, 1, NULL), e.return_flag) AS return_flag, r.RETURNED_QUANTITY AS TOTAL_RETURNED_QUANTITY, r.channel_return_reason return_reason, e.Payment_mode, e.selling_price, r.Product_name AS returned_product_name, cast(null as string) AS returned_product_variant, r.SKU AS returned_sku, r.Total_Credit_Note_Amount TOTAL_RETURN_AMOUNT, CASE WHEN e.return_flag = 1 THEN e.tax ELSE 0 END AS TOTAL_RETURN_TAX, r.Total_Credit_Note_Amount - (CASE WHEN e.return_flag = 1 THEN e.tax ELSE 0 END) AS TOTAL_RETURN_AMOUNT_EXCL_TAX, r.saleorderitemcode AS returned_item_saleorderitemcode, CASE WHEN LOWER(r.channel_return_reason) LIKE \'%exchange%\' THEN r.PRODUCT_NAME END AS exchange_product_name, CASE WHEN LOWER(r.channel_return_reason) LIKE \'%exchange%\' THEN cast(null as string) END AS exchange_product_variant, CASE WHEN LOWER(r.channel_return_reason) LIKE \'%exchange%\' THEN r.sku END AS exchange_sku, CASE WHEN LOWER(r.channel_return_reason) LIKE \'%exchange%\' THEN e.selling_price END AS exchange_product_total_price, CAST(NULL AS VARCHAR) AS exchange_status, e.order_status AS oms_order_status FROM (select * from emmasleep_db.maplemonk.emmasleep_db_sales_consolidated qualify row_number() over (partition by reference_code,saleorderitemcode order by shipping_last_update_date desc) = 1 )e LEFT JOIN maplemonk.easyecom_emmasleep_all_returns r ON replace(e.reference_code,\'#\',\'\') = r.reference_code AND e.saleorderitemcode = r.saleorderitemcode; CREATE OR REPLACE TABLE maplemonk.emmasleep_db_returns_count_data as WITH orders as ( SELECT LAST_DAY(date(order_date), MONTH) as order_month, DATE_TRUNC(\'MONTH\', order_date) as month_first_date, date(order_date) as order_date, marketplace, count(distinct reference_code) as orders_for_the_month, COUNT(DISTINCT CASE WHEN (return_flag = 1) THEN reference_code END) AS total_returned_orders_for_orders_of_month, sum(case when (return_flag=1) then 1 else 0 end) as total_returned_items_for_orders_of_month, sum(case when (return_flag=1) then TOTAL_RETURNED_QUANTITY else 0 end) as total_returned_quantity_for_orders_of_month, count(*) as total_order_items_for_the_month, sum(order_quantity) as total_order_quantity_for_the_month, sum(selling_price) as total_sales FROM maplemonk.emmasleep_db_returns_consolidated GROUP BY order_month,month_first_date, order_date,marketplace ), returns as ( SELECT LAST_DAY(DATE(return_date), MONTH) as return_month, date(return_date) as return_date, marketplace, COUNT(*) as total_returned_items_received_in_month, count(distinct reference_code) as returned_orders_received_in_month, sum(TOTAL_RETURNED_QUANTITY) as returned_quantity_received_in_month, sum(TOTAL_RETURN_AMOUNT) as total_returned_sales FROM maplemonk.emmasleep_db_returns_consolidated WHERE return_flag = 1 GROUP BY return_month,return_date,marketplace ) SELECT o.month_first_date, o.marketplace, o.order_month, o.order_date, o.orders_for_the_month, o.total_order_items_for_the_month, o.total_order_quantity_for_the_month, o.total_returned_orders_for_orders_of_month, o.total_returned_items_for_orders_of_month, o.total_returned_quantity_for_orders_of_month, o.total_sales, r.total_returned_sales, r.return_date, r.total_returned_items_received_in_month, r.returned_orders_received_in_month, r.returned_quantity_received_in_month from orders o LEFT JOIN returns r ON r.return_date = o.order_date and r.marketplace = o.marketplace order by order_date desc;",
